frappe.ui.form.on('Inspection_Out', {
    refresh(frm) {
        // Toggle visibility of the target section break
        if (!frm.is_new()) {
            frm.set_df_property('section_break_frdd', 'hidden', 0);
        } else {
            frm.set_df_property('section_break_frdd', 'hidden', 1);
        }

        // Handle 'booked_in_signature' state based on actual data existence
        if (frm.doc.booked_out_signature) {
            lock_signature_pad(frm, 'booked_out_signature');
            remove_signature_save_button(frm, 'booked_out_signature');
        } else {
            unlock_signature_pad(frm, 'booked_out_signature');
            render_signature_save_button(frm, 'booked_out_signature');
        }

        // Handle 'driver_signature' state based on actual data existence
        if (frm.doc.driver_signature) {
            lock_signature_pad(frm, 'driver_signature');
            remove_signature_save_button(frm, 'driver_signature');
        } else {
            unlock_signature_pad(frm, 'driver_signature');
            render_signature_save_button(frm, 'driver_signature');
        }
        if (frm.doc.quality_control_signature) {
            lock_signature_pad(frm, 'quality_control_signature');
            remove_signature_save_button(frm, 'quality_control_signature');
        } else {
            unlock_signature_pad(frm, 'quality_control_signature');
            render_signature_save_button(frm, 'quality_control_signature');
        }
    },

    after_save: function(frm) {
        // Evaluate inputs immediately upon successful save
        if (frm.doc.booked_out_signature) {
            lock_signature_pad(frm, 'booked_out_signature');
            remove_signature_save_button(frm, 'booked_out_signature');
        }
        if (frm.doc.driver_signature) {
            lock_signature_pad(frm, 'driver_signature');
            remove_signature_save_button(frm, 'driver_signature');
        }
        if (frm.doc.quality_control_signature) {
            lock_signature_pad(frm, 'quality_control_signature');
            remove_signature_save_button(frm, 'quality_control_signature');
        }

        // Cleanly handle accordion section snapping routines
        let attempts = 0;
        let forceLayout = setInterval(() => {
            frm.set_df_property('section_break_frdd', 'hidden', 0);

            frm.layout.fields_list.forEach(field => {
                if (field.df.fieldtype === 'Section Break') {
                    if (field.df.fieldname === 'section_break_frdd') {
                        field.collapsed = false;
                        field.collapse(false);

                        if (field.$wrapper) {
                            field.$wrapper.find('.section-body').removeClass('collapse').addClass('show');
                            field.$wrapper.find('.section-head').removeClass('collapsed').attr('aria-expanded', 'true');
                        }
                    } else {
                        field.collapsed = true;
                        field.collapse(true);
                    }
                }
            });

            attempts++;
            if (attempts > 5) {
                clearInterval(forceLayout);

                let targetSection = frm.get_field('section_break_frdd');
                if (targetSection) {
                    frappe.utils.scroll_to(targetSection.$wrapper);
                }
            }
        }, 150);
    }
});

// FREEZES canvas inputs but leaves visual data visible
function lock_signature_pad(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.signature-btn-clear').hide();
        field.$wrapper.find('.signature-display, canvas').css({
            'pointer-events': 'none',
            'opacity': '0.95'
        });
    }
}

// RESTORES canvas capabilities if the field is blank
function unlock_signature_pad(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.signature-btn-clear').show();
        field.$wrapper.find('.signature-display, canvas').css({
            'pointer-events': 'auto',
            'opacity': '1.0'
        });
    }
}

// Generates custom action buttons dynamically
function render_signature_save_button(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.custom-sig-save-btn').remove();

        let btn_html = `
            <div style="margin-top: 10px;" class="custom-sig-save-btn">
                <button class="btn btn-xs btn-primary btn-custom-save">
                    <i class="fa fa-floppy-o" style="margin-right: 5px;"></i> Save Signature
                </button>
            </div>
        `;

        field.$wrapper.append(btn_html);

        field.$wrapper.find('.btn-custom-save').on('click', function() {
            if (frm.is_dirty()) {
                frappe.show_alert({message: __('Saving changes...'), indicator: 'blue'});
                frm.save();
            } else {
                frappe.show_alert({message: __('No changes detected to save.'), indicator: 'orange'});
            }
        });
    }
}

// Utility function to cleanly drop buttons out of layout context
function remove_signature_save_button(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.custom-sig-save-btn').remove();
    }
}

