frappe.ui.form.on('Inspection_M', {
    refresh: function(frm) {
        // 1. Remove standard core print event listeners to stop the page from freezing
        frm.page.clear_primary_action(); 

        // 2. Map the appropriate custom format based on the selected company
        let target_format = 'Standard';
        if (frm.doc.company === 'Multicranes & Platforms') {
            target_format = 'Multicranes';
        } else if (frm.doc.company === 'Challenger Access Equipment') {
            target_format = 'Challenger';
        } else if (frm.doc.company === 'Multifleet Solutions') {
            target_format = 'Multifleet';
        }

        // 3. Inject our own custom routing directly onto the standard form "Print" menu option
        if (frm.page.menu) {
            // Find and target the native "Print" button on the workspace wrapper
            let print_btn = frm.page.menu.find('[data-label="Print"]');

            if (print_btn.length) {
                // Unbind Frappe's native sidebar layout loader
                print_btn.off('click').on('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    // Generate a direct, clean full-page printable URL string
                    let print_url = frappe.urllib.get_full_url(
                        `/printview?doctype=${encodeURIComponent(frm.doc.doctype)}` +
                        `&name=${encodeURIComponent(frm.doc.name)}` +
                        `&trigger_print=0` + 
                        `&format=${encodeURIComponent(target_format)}` +
                        `&no_letterhead=0`
                    );

                    // Open the tailored view instantly without loading the heavy sidebar
                    window.open(print_url, '_blank');
                });
            }
        }
    }
});
